SELECT

FROM TB_BLACKLIST_MST
WHERE 1 = 1

ORDER BY BLACKLIST_NO DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM TB_BLACKLIST_MST
WHERE BLACK_YN = 'Y'
  AND (
      (#{contact} IS NOT NULL AND #{contact} != '' AND REPLACE(REPLACE(REPLACE(BLACK_USER_CONTACT, '-', ''), ' ', ''), '.', '') = #{contact})
      OR (
          #{name} IS NOT NULL AND #{name} != ''
          AND #{birth} IS NOT NULL AND #{birth} != ''
          AND BLACK_USER_NAME = #{name}
          AND REPLACE(REPLACE(BLACK_USER_BIRTH, '-', ''), '.', '') = #{birth}
      )
  )
